using Kandra.Domain.Entities.Documents;
using Kandra.Persistence.Contexts;
using HomePantry.Domain.Identity;
using Microsoft.EntityFrameworkCore;

namespace HomePantry.Persistence.Contexts;

// DbSet<T> properties are generated by Kandra.Generators.EfConfig (one per Kandra*Entity-attributed
// type, named after its TableName) - see HomePantryDbContext.DbSets.g.cs under Generated.Net.
public partial class HomePantryDbContext : PlatformDbContext<DomainUser, DomainRole>
{
    public HomePantryDbContext(DbContextOptions options) : base(options)
    {
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        base.OnModelCreating(modelBuilder);

        modelBuilder.ApplyConfigurationsFromAssembly(typeof(HomePantryDbContext).Assembly);

        // PlatformDbContext (the engine base, above) unconditionally maps abstract DocumentBase as its
        // own entity ("Doc_Documents") for cross-document queries (Document Links/IDocumentReaderService).
        // EF Core requires at least one concrete derived type for an abstract mapped entity - this
        // configuration has none yet (zero Document types), so unmap it here. This check runs after
        // ApplyConfigurationsFromAssembly above, so it's self-healing: once you add your first Document
        // type (see the create-document skill), its generated EntityTypeConfiguration will already have
        // registered a concrete derived type by the time this check runs, and it stops applying on its
        // own - no manual cleanup needed.
        if (!modelBuilder.Model.GetEntityTypes().Any(t => typeof(DocumentBase).IsAssignableFrom(t.ClrType) && !t.ClrType.IsAbstract))
        {
            modelBuilder.Ignore<DocumentBase>();
        }

        modelBuilder.Entity<Domain.Entities.Registers.StockBalance>(b =>
        {
            b.OwnsOne(x => x.Dimensions, d =>
            {
                var uniqueIndexes = d.OwnedEntityType.GetIndexes().Where(i => i.IsUnique).ToList();
                foreach (var idx in uniqueIndexes)
                {
                    d.OwnedEntityType.RemoveIndex(idx);
                }
                d.HasIndex(nameof(Domain.Entities.Registers.StockDimensions.ProductId),
                           nameof(Domain.Entities.Registers.StockDimensions.LocationId),
                           nameof(Domain.Entities.Registers.StockDimensions.BestBeforeDate)).IsUnique();
            });
        });
    }
}
